using namespace std;

namespace
{
    using lint = long long;

    int gcd(int a, int b)
    {
        while (b != 0)
        {
            const int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    lint inverse(lint val, lint mod)
    {
        if (mod == 1)
            return 0;

        val %= mod;
        if (val < 0)
            val += mod;

        lint a = val;
        lint b = mod;
        lint x0 = 1;
        lint x1 = 0;

        while (b != 0)
        {
            const lint q = a / b;

            const lint nextA = a % b;
            a = b;
            b = nextA;

            const lint nextX = x0 - q * x1;
            x0 = x1;
            x1 = nextX;
        }

        if (a != 1)
            return 0;

        x0 %= mod;
        if (x0 < 0)
            x0 += mod;
        return x0;
    }

    pair<tuple<int, int>, bool> billiard(
        const tuple<int, int>& sz,
        const tuple<int, int>& pos,
        const tuple<int, int>& vel)
    {
        if (get<0>(sz) > get<1>(sz))
        {
            const auto res = billiard(
                make_tuple(get<1>(sz), get<0>(sz)),
                make_tuple(get<1>(pos), get<0>(pos)),
                make_tuple(get<1>(vel), get<0>(vel)));

            return {
                make_tuple(get<1>(res.first), get<0>(res.first)),
                res.second
            };
        }

        const int width = get<0>(sz);
        const int height = get<1>(sz);
        const int px = get<0>(pos);
        const int py = get<1>(pos);
        const int vx = get<0>(vel);
        const int vy = get<1>(vel);

        const lint x = (static_cast<lint>(width) + static_cast<lint>(px) * vx) % width;
        const lint y = (static_cast<lint>(height) + static_cast<lint>(py) * vy) % height;

        if (vx == 0)
        {
            if (px % width == 0)
                return {make_tuple(px, vy > 0 ? height : 0), true};
            return {make_tuple(0, 0), false};
        }

        if (vy == 0)
        {
            if (py % height == 0)
                return {make_tuple(vx > 0 ? width : 0, py), true};
            return {make_tuple(0, 0), false};
        }

        const lint c = (2LL * height - width + x - y) % height;
        const int divisor = gcd(width, height);

        if (c % divisor != 0)
            return {make_tuple(0, 0), false};

        const lint reducedC = c / divisor;
        const lint reducedWidth = width / divisor;
        const lint reducedHeight = height / divisor;

        const lint inv = inverse(reducedWidth % reducedHeight, reducedHeight);
        const lint k = reducedHeight == 1
            ? 0
            : (reducedC * inv) % reducedHeight;

        const lint t = static_cast<lint>(width) - x + k * width;
        const lint finalX = llabs(static_cast<lint>(px) + t * vx) % (2LL * width);
        const lint finalY = llabs(static_cast<lint>(py) + t * vy) % (2LL * height);

        return {
            make_tuple(static_cast<int>(finalX), static_cast<int>(finalY)),
            true
        };
