using namespace std;

using int64 = long long;
using i128 = __int128_t;

int64 extended_gcd(int64 a, int64 b, int64& x, int64& y)
{
    if (b == 0)
    {
        x = 1;
        y = 0;
        return a;
    }
    int64 x1, y1;
    int64 g = extended_gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int64 mod_inverse(int64 a, int64 mod)
{
    if (mod == 1)
        return 0;

    int64 x, y;
    if (extended_gcd(a, mod, x, y) != 1)
        return -1;

    x %= mod;
    if (x < 0)
        x += mod;
    return x;
}

int64 normalize(i128 value, int64 mod)
{
    value %= mod;
    if (value < 0)
        value += mod;
    return static_cast<int64>(value);
}

