    int64 b = normalize(-(i128)y * vy, m);
    int64 g = std::gcd(n, m);

    if ((b - a) % g != 0)
    {
        cout << -1 << '\n';
        return 0;
    }

    int64 reducedN = n / g;
    int64 reducedM = m / g;
    int64 inverse = mod_inverse(reducedN % reducedM, reducedM);

    int64 k = 0;
    if (reducedM != 1)
    {
        int64 rhs = normalize((b - a) / g, reducedM);
        k = static_cast<int64>((i128)rhs * inverse % reducedM);
