        lint b = mod;
        lint x0 = 1;
        lint x1 = 0;

        while (b != 0)
        {
            const lint q = a / b;

            const lint nextA = a - q * b;
            a = b;
            b = nextA;

            const lint nextX = x0 - q * x1;
            x0 = x1;
            x1 = nextX;
        }

        if (a != 1)
            return 0;

        x0 %= mod;
        if (x0 < 0)
            x0 += mod;
        return static_cast<int>(x0);
    }

    pair<tuple<int, int>, bool> billiard(
        const tuple<int, int>& sz,
        const tuple<int, int>& pos,
        const tuple<int, int>& vel)
    {
        if (get<0>(sz) > get<1>(sz))
        {
            const auto res = billiard(
                make_tuple(get<1>(sz), get<0>(sz)),
                make_tuple(get<1>(pos), get<0>(pos)),
                make_tuple(get<1>(vel), get<0>(vel)));

            return make_pair(
                make_tuple(get<1>(res.first), get<0>(res.first)),
                res.second);
        }

        const int x =
            (get<0>(sz) + get<0>(pos) * get<0>(vel)) % get<0>(sz);
        const int y =
            (get<1>(sz) + get<1>(pos) * get<1>(vel)) % get<1>(sz);

        if (get<0>(vel) == 0)
        {
            if (get<0>(pos) % get<0>(sz) == 0)
            {
                return make_pair(
                    make_tuple(
                        get<0>(pos),
                        get<1>(vel) > 0 ? get<1>(sz) : 0),
                    true);
            }
            return make_pair(make_tuple(0, 0), false);
        }

        if (get<1>(vel) == 0)
        {
            if (get<1>(pos) % get<1>(sz) == 0)
            {
                return make_pair(
                    make_tuple(
                        get<0>(vel) > 0 ? get<0>(sz) : 0,
                        get<1>(pos)),
                    true);
            }
            return make_pair(make_tuple(0, 0), false);
        }

        const int c =
            (get<1>(sz) - get<0>(sz) + get<1>(sz) + x - y) %
            get<1>(sz);

        const int g = gcd(c, gcd(get<0>(sz), get<1>(sz)));

        lint cdash = c;
        lint sz1dash = get<0>(sz);
        lint sz2dash = get<1>(sz);

        if (g != 0)
