            b = a%b;
            a = t;
        }
        return a;
    }
    int inverse(int val, int mod)
    {
        if(val == 0 || gcd(val, mod) != 1)
            return 0;
        lint res = 1;
        const auto ival = val;
        while(val != 1)
        {
            const auto mult = mod/val+1;
            res *= mult;
            res %= mod;
            const auto nxt = val*mult%mod;
            if(nxt != val)
            {
                val = nxt;
            }
            else
            {
                val = nxt+ival;
                res += 1;
                res %= mod;
            }
        }
        return res%mod;
    }
    pair<tuple<int, int>, bool> billiard(const tuple<int, int> &sz,
        const tuple<int, int> &pos, const tuple<int, int> &vel)
    {
        if(get<0>(sz) > get<1>(sz))
        {
            const auto res = billiard(make_tuple(get<1>(sz), get<0>(sz)),
                make_tuple(get<1>(pos), get<0>(pos)),
                make_tuple(get<1>(vel), get<0>(vel)));
            return make_pair(make_tuple(get<1>(res.first), get<0>(res.first)),
                res.second);
        }
        const auto x = (get<0>(sz)+get<0>(pos)*get<0>(vel))%get<0>(sz);
        const auto y = (get<1>(sz)+get<1>(pos)*get<1>(vel))%get<1>(sz);
        if(get<0>(vel) == 0)
        {
            if(get<0>(pos)%get<0>(sz) == 0)
            {
                return make_pair(make_tuple(
                        get<0>(pos),
                        get<1>(vel)>0?get<1>(sz):0), true);
            }
            else
            {
                return make_pair(make_tuple(0, 0), false);
            }
        }
        if(get<1>(vel) == 0)
        {
            if(get<1>(pos)%get<1>(sz) == 0)
            {
                return make_pair(make_tuple(
                        get<0>(vel)>0?get<0>(sz):0,
                        get<1>(pos)), true);
            }
            else
            {
                return make_pair(make_tuple(0, 0), false);
            }
        }
        const auto c = (get<1>(sz) - get<0>(sz)+get<1>(sz) + x - y)%get<1>(sz);
        const auto g = gcd(c, gcd(get<0>(sz), get<1>(sz)));
        lint cdash = c;
        lint sz1dash = get<0>(sz);
        lint sz2dash = get<1>(sz);
        if(g != 0)
        {
            cdash /= g;
            sz1dash /= g;
            sz2dash /= g;
        }
        const auto v = inverse(sz1dash%sz2dash, sz2dash);
        if((v*cdash%sz2dash*sz1dash%sz2dash + sz2dash - cdash)%sz2dash != 0)
            return make_pair(make_tuple(0, 0), false);
        const lint k1 = cdash*v%sz2dash;
        const lint t = (get<0>(sz) - x + k1*get<0>(sz));
        return make_pair(
            make_tuple(
                abs(get<0>(pos) + t*get<0>(vel))%(get<0>(sz)*2),
                abs(get<1>(pos) + t*get<1>(vel))%(get<1>(sz)*2)
                ), true);
    }
}

int main()
{
    tuple<int, int> sz;
    tuple<int, int> pos;
    tuple<int, int> vel;
    cin>>get<0>(sz)>>get<1>(sz);
    cin>>get<0>(pos)>>get<1>(pos);
    cin>>get<0>(vel)>>get<1>(vel);
    const auto res = billiard(sz, pos, vel);
    if(res.second)
    {
        cout<<get<0>(res.first)<<' '<<get<1>(res.first)<<endl;
    }
    else
    {
        cout<<-1<<endl;
    }
    return 0;
}
